/// Marks all leftover `running` jobs as interrupted failures. Job states only
/// move forward, so a restart cannot leave a phantom runner behind.
pub async fn fail_interrupted_jobs<C>(db: &C) -> Result<u64, DbErr>
where
  C: ConnectionTrait, {
  let mut patch = ActiveModel::new();
  patch.status = ActiveValue::Set(STATUS_FAILED.to_owned());
  patch.error_code = ActiveValue::Set(Some(ERROR_INTERRUPTED.to_owned()));
  patch.error_message = ActiveValue::Set(Some(
    "the server restarted while the job was running".to_owned(),
  ));
  patch.finished_at = ActiveValue::Set(Some(Utc::now()));
  let result = Entity::update_many()
    .set(patch)
    .filter(Column::Status.eq(STATUS_RUNNING))
    .exec(db)
    .await?;
  Ok(result.rows_affected)
}

#[cfg(test)]
mod tests {
  use super::{Model, STATUS_FAILED, STATUS_QUEUED, STATUS_RUNNING, STATUS_SUCCEEDED};

  fn job(status: &str) -> Model {
    Model {
      id: 1,
      distribution_id: 1,
      local_game_id: 2,
      trigger: "manual".to_owned(),
      status: status.to_owned(),
      old_oid: None,
      new_oid: None,
      expected_head: None,
      trace_id: "trace".to_owned(),
      error_code: None,
      error_message: None,
      log: String::new(),
      created_at: chrono::Utc::now(),
      started_at: None,
      finished_at: None,
    }
  }

  #[test]
  fn only_queued_and_running_jobs_are_active() {
    assert!(job(STATUS_QUEUED).is_active());
    assert!(job(STATUS_RUNNING).is_active());
    assert!(!job(STATUS_SUCCEEDED).is_active());
    assert!(!job(STATUS_FAILED).is_active());
  }
}
